import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.DVUHX04-.js";const p=JSON.parse('{"title":"Dependency indexes build on first query, with streamed progress","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0016-dependency-indexes-build-on-first-query.md","filePath":"adr/0016-dependency-indexes-build-on-first-query.md","lastUpdated":1789590827000}'),o={name:"adr/0016-dependency-indexes-build-on-first-query.md"};function i(r,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="dependency-indexes-build-on-first-query-with-streamed-progress" tabindex="-1">Dependency indexes build on first query, with streamed progress <a class="header-anchor" href="#dependency-indexes-build-on-first-query-with-streamed-progress" aria-label="Permalink to &quot;Dependency indexes build on first query, with streamed progress&quot;">​</a></h1><p>ADR 0003 gave every tool a <code>projectRoot</code> and, on the measured build cost (1.3 s for 390 files, 2.4 s for 1 218 files), gave a Dependency source no watcher and no prewarm. Three promises went unkept around that decision. The note&#39;s <code>projectRoot</code> line never said the first call builds and waits. The cold call streamed no progress, because the handlers ignore the update callback, so a building call looks like a hang to a human and like a failure risk to a model. And the operator&#39;s global instruction claimed &quot;each cache directory is indexed by codegraph&quot;, which the machine did not do: on 2026-09-16 the cache held 795 MB of dependency trees and zero indexes. The data matched the gap: 314 <code>opensrc path</code> calls and 987 other opensrc bash calls across about 15 dependencies, but 15 <code>projectRoot</code> calls in the same period, all against one dependency. The agent had learned to grep.</p><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><ul><li>A <code>projectRoot</code> call on a tree with no index builds the index inline and waits for it. This was already the behavior; it is now the stated contract, and a call that starts a build always finishes it.</li><li>The build streams progress through the tool&#39;s update callback (file counts, as the adapter reports them), so the wait is visible and bounded instead of silent.</li><li>The note&#39;s <code>projectRoot</code> line gains one static sentence: the first call to a dependency builds its index and may wait. The note carries no per-dependency state, so the system prompt stays stable and the provider cache stays warm.</li><li>The operator instruction changes from &quot;each cache directory is indexed&quot; to &quot;a dependency is indexed on first use; the first codegraph call may wait for the build&quot;. The promise and the machine now agree.</li><li>There is no prewarm and no background build state for a dependency tree.</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Prewarm on bash reference</strong> - watch bash commands, detect <code>opensrc path</code> or a cache path, start the build in the background. Rejected. It adds a second trigger to parse and maintain, and the price of lazy is a 1.3-2.4 s build paid by the one agent that actually asks the question.</li><li><strong>Index the whole cache on session start</strong> - 33 trees, 795 MB, a first pass of minutes and 3-5x disk per ADR 0003&#39;s measurement. Rejected. It indexes dependencies no running work uses, from every session on the machine.</li><li><strong>Time out the cold call</strong> - fail after a cap with &quot;still building, retry later&quot;. Rejected. It forces the build to outlive the call in a background state, which is a prewarm by another name. A build is bounded in seconds; the simpler contract is that the call finishes.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>After a cache update, the first agent to query a dependency waits one build (seconds); every other agent, and every later call, pays the reconcile (about 22 ms per 1 000 files per ADR 0003). The DB lives in the cache tree, so the cost is shared machine-wide per update cycle. Racing builds converge: the library runs WAL with <code>busy_timeout</code> set first, and the reconcile re-extracts only what changed.</li><li>The note line appears only when a Trusted root exists, as ADR 0003 set it; the new sentence rides on that existing bound.</li><li>The review metric for this decision is the ratio the analysis used: opensrc references against <code>projectRoot</code> calls. If the ratio does not move after the note and the progress stream land, the problem is the note&#39;s wording, not the warm-up, and the next change is to the sentence, not to the machinery.</li></ul>',8)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
